11:   const text = body === undefined ? '' : JSON.stringify(body)
12:   res.writeHead(status, { 'content-type': 'application/json', ...headers })
13:   res.end(text)
14: }
15: 
16: function readJson (req) {
17:   return new Promise((resolve, reject) => {
18:     let text = ''
19:     req.on('data', (chunk) => { text += chunk })
20:     req.on('end', () => {
21:       try { resolve(text ? JSON.parse(text) : {}) } catch (err) { reject(err) }
22:     })
23:   })
24: }
25: 
26: /** The server: routes, the rate limit in front of every one of them, the store behind. */
27: function createApp (options = {}) {
28:   const config = { ...loadConfig(), ...options }
29:   const store = options.store ?? new Store()
30:   const check = rateLimit({ limit: config.limit, windowMs: config.windowMs, ...(options.now ? { now: options.now } : {}) })
31: 
32:   return http.createServer(async (req, res) => {
33:     const verdict = check(req.socket.remoteAddress ?? 'unknown')
34:     if (!verdict.allowed) {
35:       return send(res, 429, { error: 'too many requests' }, { 'retry-after': String(verdict.retryAfterSec) })
36:     }
37:     const url = new URL(req.url, 'http://localhost')
38:     const parts = url.pathname.split('/').filter(Boolean)
39: 
40:     if (req.method === 'GET' && url.pathname === '/health') {
41:       return send(res, 200, { ok: true, service: config.serviceName })
42:     }
43:     if (parts[0] === 'items' && parts.length === 1) {
44:       if (req.method === 'GET') {
45:         const page = url.searchParams.get('page') ?? 0
46:         const limit = url.searchParams.get('limit') ?? 10
47:         return send(res, 200, paginate(store.list(), { page, limit }))
48:       }
49:       if (req.method === 'POST') {
50:         let body
51:         try { body = await readJson(req) } catch { return send(res, 400, { error: 'invalid JSON' }) }
52:         const problems = validateItem(body)
53:         if (problems.length) return send(res, 400, { error: problems.join('; ') })
54:         return send(res, 201, store.create(body))
55:       }
56:     }
57:     if (parts[0] === 'items' && parts.length === 2) {
58:       const id = Number(parts[1])
59:       if (req.method === 'GET') return send(res, 200, store.get(id))
60:       if (req.method === 'DELETE') {
61:         store.remove(id)
62:         return send(res, 204)
63:       }
64:     }
65:     return send(res, 404, { error: 'not found' })
66:   })
67: }
