export function TodoList({ todos, onToggle, onRemove, onClearCompleted }) {
  if (todos.length === 0) return <p>Nothing to do.</p>

  const activeCount = todos.filter((todo) => !todo.done).length
  const completedCount = todos.filter((todo) => todo.done).length

  return (
    <>
      <ul>
        {todos.map((todo) => (
          <TodoItem key={todo.id} todo={todo} onToggle={onToggle} onRemove={onRemove} />
        ))}
      </ul>
      <footer>
        <span>{activeCount === 1 ? '1 item left' : `${activeCount} items left`}</span>
        {completedCount > 0 && (
          <button type="button" onClick={onClearCompleted}>
            Clear completed
          </button>
        )}
      </footer>
    </>
  )
}"}

